            var result = await method(request.Params);
            return new BridgeResponse
            {
                Id = request.Id,
                Ok = true,
                Result = result
            };
        }
        catch (Exception ex)
        {
            return new BridgeResponse
            {
                Id = request.Id,
                Ok = false,
                Error = new BridgeError
                {
                    Code = "INTERNAL_ERROR",
                    Message = ex.Message
                }
            };
        }
