// Vite configuration for the 3dm React UI embedded in Rhino WebView2.
// Configuration MUST include React and Tailwind CSS plugins.

import react from "@vitejs/plugin-react";
import path from "path";
import { fileURLToPath } from "url";
import { defineConfig } from "vite";
import topLevelAwait from "vite-plugin-top-level-await";
import wasm from "vite-plugin-wasm";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

export default defineConfig(async () => {
  const tailwind = await import("@tailwindcss/vite");
  return {
    resolve: {
      alias: {
        "@semio-tech/compose-js": path.resolve(__dirname, "../../js"),
      },
    },
    plugins: [
      tailwind.default(),
      react(),
      wasm(),
      topLevelAwait(),
    ],
    optimizeDeps: {
      exclude: ["@semio-tech/compose-js"],
      esbuildOptions: {
        target: "es2020",
      },
    },
    build: {
      outDir: "dist",
    },
  };
});
// #endregion 🔖Configuration
```

### **Key findings:**

1. **CSS Pattern**: All projects use `@import "compose/js/globals.css"` to access the shared CSS from `compose/js`, plus local Tailwind + xyflow
2. **Vite alias resolution**: The **3dm/ui** project shows the proper `resolve.alias` pattern: `"@semio-tech/compose-js": path.resolve(__dirname, "../../js")`
3. **docs doesn't have vite.config.ts** — uses a different build setup
4. **play uses complex Vite config** with MDX, remark plugins, and likely has more extensive alias resolution beyond the first 40 lines

